'use strict';
const WELLBEING_MOODS=['Good','Okay','Low energy','Overwhelmed','Need quiet'];
const DEBRIEF_FIELDS=[['highlight','What was your favorite part?','A little moment you’d like to remember…'],['unspoken','Anything still on your mind?','Something I didn’t quite get to say…'],['next','What would you love to do next time?','A small idea for our next hangout…']];
let wellbeingDraft=null;
function ensureExtras(){
 if(!state.wellbeingByDay||typeof state.wellbeingByDay!=='object'||Array.isArray(state.wellbeingByDay))state.wellbeingByDay={};
 if(!Array.isArray(state.debriefs))state.debriefs=[];
 state.debriefs=state.debriefs.filter(d=>d&&typeof d.id==='string'&&typeof d.title==='string'&&typeof d.date==='string'&&d.answers&&typeof d.answers==='object'&&d.share&&typeof d.share==='object');
}
function wellbeing(){ensureExtras();const w=state.wellbeingByDay[state.date];if(!w||!WELLBEING_MOODS.includes(w.mood)&&w.mood!==''||typeof w.need!=='string'||!w.share){state.wellbeingByDay[state.date]={mood:'',need:'',device:false,share:{mood:false,need:false,sleep:false,readiness:false}};}return state.wellbeingByDay[state.date];}
function sharedWellbeing(w){const list=[];if(w.share.mood&&w.mood)list.push(['Feeling',w.mood]);if(w.share.need&&w.need.trim())list.push(['What would help',w.need]);if(w.device&&w.share.sleep)list.push(['Sleep · Oura sample','6h 12m']);if(w.device&&w.share.readiness)list.push(['Readiness · Oura sample','68 / 100']);return list;}
function optionalTools(){const w=wellbeing(),shares=sharedWellbeing(w);return `<section class="optional-section" aria-label="Optional ways to connect"><div class="optional-heading"><div><span class="eyebrow">A LITTLE MORE, IF YOU FEEL LIKE IT</span><h2>Your day. Your pace.</h2></div><span class="optional-pill">Always optional</span></div><p class="optional-subtitle">Pick what feels useful. These extras never affect your shared streak.</p><div class="optional-grid"><article class="extra-card"><div class="extra-title"><span class="extra-icon">${icon('sun')}</span><span class="eyebrow">HOW I’M DOING</span><span class="private-badge">${icon(shares.length?'us':'lock')}${shares.length?'Sharing preview':'Private'}</span></div><h3>${w.mood?esc(w.mood):'A little context.<br>A little more care.'}</h3><p>${w.need?esc(w.need):'Let your partner know how you feel and what would help today.'}</p>${w.device?'<div class="sample-metrics"><span><strong>6h 12m</strong>Sleep</span><span><strong>68</strong>Readiness</span><small>Oura sample · not connected</small></div>':''}<button class="secondary" data-extra="wellbeing">${w.mood?'Update my day':'Check in with myself'} ${icon('arrow')}</button><button class="extra-text-button" data-extra="wearable">${w.device?'Manage wearable preview':'Explore wearable preview'}</button></article><article class="extra-card"><div class="extra-title"><span class="extra-icon lilac">${icon('book')}</span><span class="eyebrow">AFTER TIME TOGETHER</span></div><h3>How did our<br>hangout feel?</h3><p>A little reflection after a walk, a date, or just a quiet night in. Share only what you choose.</p><div class="debrief-prompt">“My favorite little part was…”</div><button class="secondary" data-extra="debrief">Write a hangout debrief ${icon('arrow')}</button><span class="extra-footnote">${state.debriefs.length?state.debriefs.length+' saved reflection'+(state.debriefs.length===1?'':'s'):'Private first. No perfect words needed.'}</span></article></div></section>`;}
function extraSettings(){return `<div class="settings-section"><p class="eyebrow">MY DAY, MY CHOICE</p><div class="settings-group"><button class="setting-row" data-extra="wellbeing"><div><span>Wellbeing & sharing</span><p>Choose what your partner would see</p></div>${icon('chevron')}</button><button class="setting-row" data-extra="wearable"><div><span>Wearable preview</span><p>Oura sample data · no device connected</p></div>${icon('chevron')}</button><button class="setting-row" data-extra="debrief"><div><span>Hangout debrief</span><p>A private reflection, with optional sharing</p></div>${icon('chevron')}</button></div></div>`;}
function shareCheck(key,label,checked,disabled=false){return `<label class="share-check ${disabled?'unavailable':''}"><input type="checkbox" id="wb-share-${key}" ${checked?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`;}
function openWellbeing(){const w=wellbeing();wellbeingDraft=JSON.parse(JSON.stringify(w));modalName='wellbeing';modal('How I’m doing today.',`<p>Your words describe your feelings. Wearable readings can add a little context.</p><form id="wellbeing-form"><label for="wb-mood">How are you feeling?</label><select id="wb-mood"><option value="">Choose how you feel</option>${WELLBEING_MOODS.map(m=>`<option value="${m}" ${w.mood===m?'selected':''}>${m}</option>`).join('')}</select><label for="wb-need">What would help today? <span class="muted-inline">Optional</span></label><textarea id="wb-need" maxlength="300" placeholder="A hug, a quiet evening, a little encouragement…">${esc(w.need)}</textarea><div class="wearable-inline"><span>${icon('leaf')} ${w.device?'Oura sample added':'Want more context?'}</span><button type="button" class="extra-text-button" data-extra="wearable-from-form">${w.device?'Manage sample':'Explore wearable preview'}</button></div><fieldset class="share-fieldset"><legend>What would ${esc(state.partner)} see?</legend><p>Nothing is shared by default. Pick each item yourself.</p>${shareCheck('mood','My mood',w.share.mood)}${shareCheck('need','What would help me',w.share.need)}${shareCheck('sleep','My sleep summary · sample',w.share.sleep,!w.device)}${shareCheck('readiness','My readiness summary · sample',w.share.readiness,!w.device)}</fieldset><p class="inset-note">Sharing is simulated in this demo. No health data is imported and nothing is sent to your partner.</p><button type="submit" class="primary">Save my day ${icon('check')}</button></form><button class="secondary" data-extra="partner-view">Preview what my partner sees</button>${sharedWellbeing(w).length?'<button class="extra-text-button full" data-extra="pause-sharing">Make everything private</button>':''}`);}
function captureWellbeing(){const mood=$('#wb-mood');if(!mood)return null;return {mood:mood.value,need:$('#wb-need').value.trim().slice(0,300),device:wellbeingDraft?.device??false,share:{mood:$('#wb-share-mood').checked,need:$('#wb-share-need').checked,sleep:!!wellbeingDraft?.device&&$('#wb-share-sleep').checked,readiness:!!wellbeingDraft?.device&&$('#wb-share-readiness').checked}};}
function saveWellbeing(){const w=captureWellbeing();if(!w)return;state.wellbeingByDay[state.date]=w;persist();closeModal();render();toast(sharedWellbeing(w).length?'Saved. Only your selected items appear in the sharing preview.':'Saved privately. Your shared streak is unchanged.');}
function partnerWellbeingView(){const draft=captureWellbeing(),w=draft||wellbeing(),list=sharedWellbeing(w);if(draft){wellbeingDraft=draft;}modalName='partner-view';modal('Through their eyes.',`<p>This is what ${esc(state.partner)} would see for ${esc(state.me)}. This preview does not send anything.</p>${list.length?`<div class="partner-preview-heading"><span class="mini-avatar">${esc(state.me.charAt(0))}</span><span>${esc(state.me)}’s day</span><small>${prettyDate(state.date,{month:'short',day:'numeric'})}</small></div>${list.map(([label,value])=>`<div class="preview-item"><span>${esc(label)}</span><p>${esc(value)}</p></div>`).join('')}`:`<div class="private-empty">${icon('lock')}<h3>Just for you, for now.</h3><p>No wellbeing items are selected for sharing.</p></div>`}<p class="inset-note" style="margin-top:20px">A sleep or readiness score is context, not a description of your emotions. Only you can say how you feel.</p><button class="primary" data-extra="back-wellbeing">Back to my choices ${icon('arrow')}</button>`);}
function openWearable(fromForm=false){if(fromForm){const draft=captureWellbeing();if(draft)wellbeingDraft=draft;}const w=wellbeingDraft||wellbeing();modalName='wearable';modal('A little more context.',`<p>Explore how a wearable could add context to your day. You decide what your partner would see.</p><div class="wearable-device"><span class="ring-glyph" aria-hidden="true"></span><div><h3>Oura Ring</h3><span class="sample-label">SAMPLE DATA · NOT CONNECTED</span></div></div><div class="sample-metrics wearable-metrics"><span><strong>6h 12m</strong>Sleep summary</span><span><strong>68 / 100</strong>Readiness summary</span></div><p class="inset-note">This only adds sample readings. It does not sign in to Oura, access your ring, or share your health information.</p><p class="wearable-future">Apple Watch, Fitbit, and Garmin are ideas for later. Their connections aren’t available in this demo.</p><button class="primary" data-extra="add-device">${w.device?'Keep sample readings':'Try Oura sample readings'} ${icon('arrow')}</button>${w.device?'<button class="secondary" data-extra="remove-device">Remove sample readings</button>':''}<button class="extra-text-button full" data-extra="back-wellbeing">Back to my wellbeing</button>`);}
function backToWellbeing(){const draft=wellbeingDraft;openWellbeing();if(draft){wellbeingDraft=draft;$('#wb-mood').value=draft.mood;$('#wb-need').value=draft.need;for(const k of ['mood','need','sleep','readiness']){const el=$('#wb-share-'+k);el.checked=!!draft.share[k];el.disabled=(k==='sleep'||k==='readiness')&&!draft.device;}$('.wearable-inline span').innerHTML=icon('leaf')+' '+(draft.device?'Oura sample added':'Want more context?');}}
function toggleDevice(on){let w=wellbeingDraft||JSON.parse(JSON.stringify(wellbeing()));w.device=on;if(!on){w.share.sleep=false;w.share.readiness=false;}wellbeingDraft=w;backToWellbeing();toast(on?'Oura sample added. Choose whether to share it.':'Sample readings removed.');}
function sharedDebrief(d){const list=[];for(const [key,label]of DEBRIEF_FIELDS){if(d.share[key]&&d.answers[key]?.trim())list.push([label,d.answers[key]]);}if(d.share.connected&&d.answers.connected)list.splice(1,0,['How connected I felt',d.answers.connected+' out of 5']);return list;}
function debriefMemories(){ensureExtras();return `<section class="debrief-history"><div class="history-head"><h2>AFTER OUR TIME TOGETHER</h2><button class="extra-text-button" data-extra="debrief">Write a debrief ${icon('arrow')}</button></div>${state.debriefs.length?`<div class="history-list">${[...state.debriefs].reverse().map(d=>`<button class="memory-row" data-extra="debrief-detail" data-id="${esc(d.id)}"><span class="date-tile"><span>${prettyDate(d.date,{month:'short'})}</span><strong>${prettyDate(d.date,{day:'numeric'})}</strong></span><span class="memory-text"><span>Hangout debrief · ${sharedDebrief(d).length?'Selected answers shared in preview':'Private reflection'}</span><span class="memory-title">${esc(d.title)}</span></span>${icon('chevron')}</button>`).join('')}</div>`:`<div class="debrief-empty">${icon('book')}<p>A favorite little part. Something still on your mind. Your reflections can live here.</p><button class="secondary" data-extra="debrief">Write your first debrief</button></div>`}</section>`;}
function debriefForm(id){ensureExtras();const d=state.debriefs.find(x=>x.id===id)||{id:'',title:'',date:state.date,answers:{highlight:'',unspoken:'',next:'',connected:''},share:{highlight:false,unspoken:false,next:false,connected:false}};modalName='debrief';modal('After time together.',`<p>No need to rate the hangout or your partner. Just notice how it felt for you.</p><form id="debrief-form" data-id="${esc(d.id)}"><label for="db-title">What did you do together?</label><input id="db-title" maxlength="60" placeholder="Coffee, a walk, a cozy night in…" value="${esc(d.title)}"><span class="form-date">${prettyDate(d.date,{month:'long',day:'numeric'})} · Everything is optional</span>${DEBRIEF_FIELDS.map(([key,label,hint],i)=>`${i===1?`<div class="debrief-field"><label for="db-connected">How connected did you feel?</label><select id="db-connected"><option value="">Skip this question</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${String(d.answers.connected)===String(n)?'selected':''}>${n} — ${['A little distant','Somewhat distant','Somewhere in the middle','Connected','Really connected'][n-1]}</option>`).join('')}</select><label class="share-check"><input type="checkbox" id="db-share-connected" ${d.share.connected?'checked':''}><span>Share this answer in the partner preview</span></label></div>`:''}<div class="debrief-field"><label for="db-${key}">${label}</label><textarea id="db-${key}" maxlength="600" placeholder="${hint}">${esc(d.answers[key])}</textarea><label class="share-check"><input type="checkbox" id="db-share-${key}" ${d.share[key]?'checked':''}><span>Share this answer in the partner preview</span></label></div>`).join('')}<p class="inset-note">Your reflection starts private. Choose individual answers to include in the partner preview. Nothing is sent in this demo.</p><p id="db-error" class="error-text" role="alert"></p><button type="submit" class="primary">Save my debrief ${icon('check')}</button></form>`);}
function saveDebrief(form){const id=form.dataset.id,previous=state.debriefs.find(d=>d.id===id);const answers={connected:$('#db-connected').value};const share={connected:$('#db-share-connected').checked};for(const [key]of DEBRIEF_FIELDS){answers[key]=$('#db-'+key).value.trim().slice(0,600);share[key]=$('#db-share-'+key).checked;}if(!Object.values(answers).some(Boolean)){$('#db-error').textContent='Add one little reflection or choose how connected you felt.';return;}const d={id:previous?.id||'debrief-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),date:previous?.date||state.date,title:$('#db-title').value.trim().slice(0,60)||'Time together',answers,share};if(previous)state.debriefs[state.debriefs.indexOf(previous)]=d;else state.debriefs.push(d);persist();closeModal();render();debriefDetail(d.id);toast('Reflection saved. Your daily Moment and streak are unchanged.');}
function debriefDetail(id,partner=false){const d=state.debriefs.find(x=>x.id===id);if(!d)return;const fields=partner?sharedDebrief(d):DEBRIEF_FIELDS.filter(([k])=>d.answers[k]).map(([key,label])=>[label,d.answers[key],d.share[key]]);if(!partner&&d.answers.connected)fields.splice(1,0,['How connected I felt',d.answers.connected+' out of 5',d.share.connected]);modalName='debrief-detail';modal(esc(d.title),`<div class="detail-meta">${prettyDate(d.date,{month:'long',day:'numeric'})} · ${partner?'PARTNER VIEW PREVIEW':'YOUR REFLECTION'}</div>${partner?'<p class="inset-note">Only selected answers appear here. This preview does not send anything.</p>':'<p class="inset-note">Your own view includes private answers. The partner preview includes only answers you chose to share.</p>'}${fields.length?fields.map(([label,value,shared])=>`<div class="preview-item"><span>${esc(label)}${!partner?`<small>${shared?'Included in partner preview':'Private'}</small>`:''}</span><p>${esc(value)}</p></div>`).join(''):`<div class="private-empty">${icon('lock')}<h3>This one is just for you.</h3><p>No answers were selected for sharing.</p></div>`}${partner?`<button class="primary" data-extra="debrief-detail" data-id="${esc(id)}">Back to my reflection</button>`:`<button class="primary" data-extra="debrief-partner" data-id="${esc(id)}">Preview partner view ${icon('arrow')}</button><button class="secondary" data-extra="debrief-edit" data-id="${esc(id)}">Edit reflection & sharing</button>`}`);}
document.addEventListener('submit',e=>{if(e.target.id==='wellbeing-form'){e.preventDefault();saveWellbeing();}if(e.target.id==='debrief-form'){e.preventDefault();saveDebrief(e.target);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-extra]');if(!b)return;const a=b.dataset.extra;if(a==='wellbeing'){wellbeingDraft=null;openWellbeing();}else if(a==='wearable'){wellbeingDraft=null;openWearable();}else if(a==='wearable-from-form')openWearable(true);else if(a==='back-wellbeing')backToWellbeing();else if(a==='add-device')toggleDevice(true);else if(a==='remove-device')toggleDevice(false);else if(a==='partner-view')partnerWellbeingView();else if(a==='pause-sharing'){const w=wellbeing();w.share={mood:false,need:false,sleep:false,readiness:false};persist();closeModal();render();toast('All wellbeing items are private.');}else if(a==='debrief')debriefForm();else if(a==='debrief-edit')debriefForm(b.dataset.id);else if(a==='debrief-detail')debriefDetail(b.dataset.id);else if(a==='debrief-partner')debriefDetail(b.dataset.id,true);});
